# Car symptom definitions (11-14, Lemon growth project 2C): the text patterns that find each symptom in NHTSA owner complaints,
# plus what we say about it (causes, how serious, FAQ) in our own words, kept general. Used by symptoms.py (the scan) and symptom_pages.py.
import re

SHAKE = r'shak(?:e|es|ing|y)|shook|vibrat\w*|shudder\w*|pulsat\w*|wobbl\w*'
BRAKE = r'\bbrak(?:e|es|ing|ed)\b|\bstopping\b|slowing down'
TURN = r'when (?:i |you )?(?:turn|turning)\b|while turning|during (?:a )?turns?|making (?:a |sharp |tight )?(?:left|right|u-?|sharp|tight)? ?turns?|turning (?:the (?:steering )?wheel|left|right|sharp|corners?)|(?:sharp|tight|slow|low[- ]speed) turns?|\bturns? (?:left|right)\b|steering wheel is turned|full lock'
ACCEL = r'accelerat\w*|speed(?:ing)? up|gas pedal|from a (?:complete )?stop|press(?:ing|ed)? (?:on )?the (?:gas|accelerator)|step(?:ping|ped)? on the (?:gas|accelerator)|under load|merging'
NOSTART = r"(?:won'?t|wont|would not|wouldn'?t|will not|did not|didn'?t|does not|doesn'?t|failed to|fail(?:s|ed)? to|could not|couldn'?t|not) (?:re-?)?start|no[- ]start|not starting|hard to start|difficult to start"
STALL = r"\bstall(?:s|ed|ing)?\b|engine (?:shut|cut|turned|turns|shuts|cuts) (?:off|out|down)|(?:shut|cut)s? (?:off|out|down) (?:while|when|on its own|by itself|in traffic|without warning|unexpectedly)|(?:vehicle|car|engine|truck|suv) died|died (?:while|on the|in traffic|at)"

def near(a, b, n=40):
    """a and b in the same sentence, within n characters, either order"""
    return rf'(?:{a})[^.!?\n]{{0,{n}}}(?:{b})|(?:{b})[^.!?\n]{{0,{n}}}(?:{a})'

