# a complaint counts for this page when BOTH patterns match somewhere in its text
BOTH = {'car-shaking-and-check-engine-light-on': (SHAKE + r'|rough(?:ly)? idl|running rough|runs rough', r'check engine|service engine|engine (?:warning )?light|\bcel\b|malfunction indicator')}

RX = {k: (re.compile(v[2], re.I) if v[2] else None, re.compile(v[3], re.I) if v[3] else None) for k, v in P.items()}
RXB = {k: (re.compile(a, re.I), re.compile(b, re.I)) for k, (a, b) in BOTH.items()}

def match(text):
    """symptom ids whose pattern matches the complaint text"""
    out = []
    for k, (rx, nx) in RX.items():
        if k in RXB:
            a, b = RXB[k]
            pa = [m.start() for m in a.finditer(text)]   # within 250 characters of each other
            if pa and any(abs(m.start() - x) <= 250 for m in b.finditer(text) for x in pa): out.append(k)
            continue
        m = rx.search(text)
        if not m: continue
        if nx:
            # the must-not pattern only vetoes when it sits in the same sentence as the match
            s0 = max(text.rfind('.', 0, m.start()), text.rfind('\n', 0, m.start())) + 1; e = [i for i in (text.find('.', m.end()), text.find('\n', m.end())) if i >= 0]
            sent = text[s0:min(e) if e else len(text)]
            if nx.search(sent):
                # try the next match in the text before giving up
                ok = False
                for m2 in rx.finditer(text, m.end()):
                    s0 = max(text.rfind('.', 0, m2.start()), text.rfind('\n', 0, m2.start())) + 1; e = [i for i in (text.find('.', m2.end()), text.find('\n', m2.end())) if i >= 0]
                    if not nx.search(text[s0:min(e) if e else len(text)]): ok = True; break
                if not ok: continue
        out.append(k)
    return out
